from collections.abc import Iterator
from datetime import date, timedelta

_LIMIT = date(3000, 1, 1)
_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _year_month(base_year: int, base_month: int, offset: int) -> tuple[int, int]:
    idx = base_year * 12 + (base_month - 1) + offset
    return idx // 12, idx % 12 + 1


def _days_in_month(year: int, month: int) -> int:
    nxt = date(year + month // 12, month % 12 + 1, 1)
    return (nxt - date(year, month, 1)).days


def _occurrences(start: date, tokens: list[str]) -> Iterator[date]:
    kind = tokens[0]

    if kind == "DAILY":
        step = int(tokens[1])
        d = start
        while d < _LIMIT:
            yield d
            d += timedelta(days=step)

    elif kind == "WEEKLY":
        step = int(tokens[1])
        days = sorted({_WEEKDAYS[c] for c in tokens[2].split(",")})
        monday = start - timedelta(days=start.weekday())
        w = 0
        while True:
            week_start = monday + timedelta(weeks=w)
            if week_start > _LIMIT:
                return
            for wd in days:
                d = week_start + timedelta(days=wd)
                if d >= _LIMIT:
                    return
                if d >= start:
                    yield d
            w += step

    elif kind == "MONTHLY" and len(tokens) == 3:
        step = int(tokens[1])
        day = int(tokens[2])
        j = 0
        while True:
            y, m = _year_month(start.year, start.month, j)
            if date(y, m, 1) >= _LIMIT:
                return
            dim = _days_in_month(y, m)
            target = dim if day == -1 else day
            if target <= dim:
                d = date(y, m, target)
                if d >= _LIMIT:
                    return
                if d >= start:
                    yield d
            j += step

    elif kind == "MONTHLY":
        step = int(tokens[1])
        nth = int(tokens[2])
        wd = _WEEKDAYS[tokens[3]]
        j = 0
        while True:
            y, m = _year_month(start.year, start.month, j)
            first = date(y, m, 1)
            if first >= _LIMIT:
                return
            dim = _days_in_month(y, m)
            if nth > 0:
                target = 1 + (wd - first.weekday()) % 7 + 7 * (nth - 1)
            else:
                last = date(y, m, dim)
                target = dim - (last.weekday() - wd) % 7
            if 1 <= target <= dim:
                d = date(y, m, target)
                if d >= _LIMIT:
                    return
                if d >= start:
                    yield d
            j += step

    elif kind == "YEARLY":
        step = int(tokens[1])
        mm, dd = (int(x) for x in tokens[2].split("-"))
        j = 0
        while True:
            y = start.year + j * step
            if y >= _LIMIT.year:
                return
            try:
                d = date(y, mm, dd)
            except ValueError:
                pass
            else:
                if d >= start:
                    yield d
            j += 1


def recur(start: str, rule: str, count: int) -> list[str]:
    result: list[str] = []
    for d in _occurrences(date.fromisoformat(start), rule.split(" ")):
        result.append(d.isoformat())
        if len(result) == count:
            break
    return result
